import random

def evaluate(current_reputation, observation, my_history, round_num):
    # Weight for past reputation; lower alpha means more weight to recent actions
    alpha = 0.3
    if observation['action'] == 'cooperate':
        observation_score = 1.0
    else:
        observation_score = -1.0
    # Combine with exponential moving average to recency‑bias reputation updates
    new_reputation = alpha * current_reputation + (1 - alpha) * observation_score
    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    # Be unconditionally cooperative in the first two rounds (build initial trust)
    if round_num <= 2:
        return True
    # Thereafter, cooperate only if the recipient's reputation is above a threshold
    if recipient_reputation >= -0.3:
        return True
    else:
        return False
