import random

def evaluate(current_reputation, observation, my_history, round_num):
    # Slower decay to preserve reputation longer
    decay = 0.05
    if observation['action'] == 'cooperate':
        increment = 0.4
        # Extra encouragement for cooperation in early rounds (first 5)
        if round_num < 5:
            increment += 0.1
    else:
        increment = -1.0  # harsher punishment for defection
    # Standard exponential moving average update
    new_rep = (1 - decay) * current_reputation + increment
    # Clamp to valid range
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Base threshold increases with rounds (starts at 0.0)
    threshold = 0.0 + 0.1 * round_num

    # Adjust threshold based on our own past behaviour
    if my_history:
        own_coops = sum(my_history)
        own_defects = len(my_history) - own_coops
        if own_coops > own_defects:
            threshold -= 0.1   # more forgiving if we have cooperated more
        elif own_defects > own_coops:
            threshold += 0.1   # stricter if we have defected more
        # if equal, no adjustment

    # Hard boundaries for extreme reputations
    if recipient_reputation > 0.9:
        return True
    if recipient_reputation < -0.9:
        return False

    # Final decision based on threshold
    return recipient_reputation > threshold
