def evaluate(current_reputation, observation, my_history, round_num):
    alpha = 0.2
    if observation['action'] == 'cooperate':
        target = 1.0
    else:
        target = -1.0
    new_rep = current_reputation * (1 - alpha) + target * alpha
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Early rounds: cooperate unconditionally to build a good reputation
    if round_num < 5:
        return True

    # Adjust threshold based on how many times we have defected ourselves
    my_defections = sum(1 for entry in my_history if entry['my_action'] == 'defect')
    threshold = -0.1 * my_defections  # becomes more negative with more defections (more likely to cooperate)
    return recipient_reputation > threshold
