import random

def evaluate(current_reputation, observation, my_history, round_num):
    # Map action to a value: cooperates gives 0.8, defect gives -0.8
    action_value = 0.8 if observation['action'] == 'cooperate' else -0.8
    # Half-life update: equal weight to current reputation and new observation
    new_reputation = 0.5 * current_reputation + 0.5 * action_value
    # Clamp to valid range [-1, 1]
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # No special early rounds; base decision on reputation
    # Cooperate if reputation is positive
    if recipient_reputation > 0.0:
        return True
    # If I cooperated in the previous round, I'm more forgiving (30% chance)
    if len(my_history) > 0 and my_history[-1]:
        if random.random() < 0.3:
            return True
    # Small chance of random forgiveness to maintain some cooperation
    if random.random() < 0.05:
        return True
    return False
